51	/* ───────────────────────────────────────────
52	 * Event Bus Types
53	 * ─────────────────────────────────────────── */
54	typedef enum {
55	    EVT_RECORD_INGESTED,
56	    EVT_VALID_RECORD,
57	    EVT_INVALID_RECORD,
58	    EVT_TRANSFORMED_RECORD,
59	    EVT_TERMINATE,
60	    EVT__COUNT
61	} evt_type_t;
