118	static char *now_utc_iso(char buf[32]) {
119	    time_t t = time(NULL);
120	    struct tm tm;
121	    gmtime_r(&t, &tm);
122	    strftime(buf, 32, "%Y-%m-%dT%H:%M:%SZ", &tm);
123	    return buf;
124	}
