177	/* ───────────────────────────────────────────
178	 * Transformer Observer – demo: upper-case first field
179	 * ─────────────────────────────────────────── */
180	typedef struct {
181	    app_ctx_t *app;
182	} transformer_ctx_t;
183	
184	static void str_toupper(char *s) {
185	    for (; *s; ++s) *s = (char) toupper((unsigned char)*s);
186	}
187	
188	static void transformer_cb(const event_t *ev, void *ctx_void) {
189	    transformer_ctx_t *ctx = ctx_void;
190	    if (ev->type != EVT_VALID_RECORD) return;
191	
192	    record_t *rec = ev->record;
193	    if (rec->field_count > 0) str_toupper(rec->fields[0]);
194	
195	    event_t next = {
196	        .type   = EVT_TRANSFORMED_RECORD,
197	        .record = rec
198	    };
199	    bus_publish(&ctx->app->bus, &next);
200	}
