241	 * Dashboard Observer – ncurses live counter
242	 * ─────────────────────────────────────────── */
243	typedef struct {
244	    unsigned long ingested;
245	    unsigned long valid;
246	    unsigned long invalid;
247	    unsigned long stored;
248	} dash_stats_t;
