255	static void dashboard_render(dash_ctx_t *d) {
256	    mvprintw(1, 2, "Ingested : %lu", d->stats.ingested);
257	    mvprintw(2, 2, "Valid    : %lu", d->stats.valid);
258	    mvprintw(3, 2, "Invalid  : %lu", d->stats.invalid);
259	    mvprintw(4, 2, "Stored   : %lu", d->stats.stored);
260	    refresh();
261	}
262	
263	static void dashboard_cb(const event_t *ev, void *ctx_void) {
264	    dash_ctx_t *d = ctx_void;
265	    switch (ev->type) {
266	        case EVT_RECORD_INGESTED:     d->stats.ingested++; break;
267	        case EVT_VALID_RECORD:        d->stats.valid++;    break;
268	        case EVT_INVALID_RECORD:      d->stats.invalid++;  break;
269	        case EVT_TRANSFORMED_RECORD:  d->stats.stored++;   break;
270	        default: break;
271	    }
272	    dashboard_render(d);
273	}
