275	/* ───────────────────────────────────────────
276	 * Simple CSV parser
277	 * ─────────────────────────────────────────── */
278	static int parse_csv_line(char *line, char **fields, int max_fields) {
279	    int count = 0;
280	    char *p = line;
281	    while (*p && count < max_fields) {
282	        fields[count++] = p;
283	        char *comma = strchr(p, ',');
284	        if (!comma) break;
285	        *comma = '\0';
286	        p = comma + 1;
287	    }
288	    return count;
289	}
