291	/* ───────────────────────────────────────────
292	 * Ingestion – from FILE*
293	 * ─────────────────────────────────────────── */
294	static void ingest_stream(FILE *fp, app_ctx_t *app) {
295	    char line[LINE_MAX_LEN];
296	    while (fgets(line, sizeof line, fp)) {
297	        size_t len = strlen(line);
298	        if (len && line[len - 1] == '\n') line[len - 1] = '\0';
299	
300	        record_t *rec = calloc(1, sizeof(*rec));
301	        if (!rec) fatal("calloc");
302	
303	        strncpy(rec->raw, line, LINE_MAX_LEN - 1);
304	        rec->field_count = parse_csv_line(rec->raw, rec->fields, FIELD_MAX);
305	
306	        event_t ev = {.type = EVT_RECORD_INGESTED, .record = rec};
307	        bus_publish(&app->bus, &ev);
308	    }
309	
310	    event_t term = {.type = EVT_TERMINATE, .record = NULL};
311	    bus_publish(&app->bus, &term);
312	}
