331	/* ───────────────────────────────────────────
332	 * SQLite helpers
333	 * ─────────────────────────────────────────── */
334	static void db_init(sqlite3 **out_db, const char *path) {
335	    if (sqlite3_open(path, out_db) != SQLITE_OK)
336	        fatal("sqlite3_open");
337	
338	    const char *ddl =
339	        "CREATE TABLE IF NOT EXISTS records ("
340	        "id INTEGER PRIMARY KEY AUTOINCREMENT,"
341	        "created_at TEXT,"
342	        "col0 TEXT, col1 TEXT, col2 TEXT, col3 TEXT, col4 TEXT);";
343	    char *errmsg = NULL;
344	    if (sqlite3_exec(*out_db, ddl, NULL, NULL, &errmsg) != SQLITE_OK) {
345	        fprintf(stderr, "SQLite DDL error: %s\n", errmsg);
346	        sqlite3_free(errmsg);
347	        exit(EXIT_FAILURE);
348	    }
349	}
