354	static void usage(const char *prog) {
355	    printf("Usage: %s [OPTIONS] <input-file>|-\n", prog);
356	    puts("Options:");
357	    puts("  -s, --schema <path>    Path to CSV header schema file");
358	    puts("  -d, --db     <path>    SQLite database path");
359	    puts("  -q, --quiet            Disable dashboard (ncurses)");
