363	/* ───────────────────────────────────────────
364	 * Entry point
365	 * ─────────────────────────────────────────── */
366	int main(int argc, char **argv) {
367	    const char *schema_path = NULL;
368	    const char *db_path = DB_PATH_DEFAULT;
369	    bool dash_enabled = true;
370	
371	    static struct option long_opts[] = {
372	        {"schema", required_argument, 0, 's'},
373	        {"db",     required_argument, 0, 'd'},
374	        {"quiet",  no_argument,       0, 'q'},
375	        {"help",   no_argument,       0, 'h'},
376	        {0,0,0,0}
377	    };
378	
379	    int opt;
380	    while ((opt = getopt_long(argc, argv, "s:d:qh", long_opts, NULL)) != -1) {
381	        switch (opt) {
382	            case 's': schema_path = optarg; break;
383	            case 'd': db_path     = optarg; break;
384	            case 'q': dash_enabled = false; break;
385	            case 'h': usage(argv[0]); return 0;
386	            default:  usage(argv[0]); return 1;
387	        }
388	    }
389	
390	    if (optind >= argc) {
391	        usage(argv[0]);
392	        return 1;
393	    }
394	
395	    const char *input_path = argv[optind];
396	
397	    /* ───── Initialization ───── */
398	    app_ctx_t app = {0};
399	    app.dashboard_enabled = dash_enabled;
400	    bus_init(&app.bus);
401	
402	    if (schema_path) schema_load(schema_path, &app.schema);
403	    else {
404	        fprintf(stderr, "Schema is required (-s)\n");
405	        return 1;
406	    }
407	
408	    db_init(&app.db, db_path);
409	
410	    /* Validator */
411	    validator_ctx_t vctx = {.app = &app};
412	    bus_subscribe(&app.bus, EVT_RECORD_INGESTED, validator_cb, &vctx);
413	
414	    /* Transformer */
415	    transformer_ctx_t tctx = {.app = &app};
416	    bus_subscribe(&app.bus, EVT_VALID_RECORD, transformer_cb, &tctx);
417	
418	    /* Storage */
419	    storage_ctx_t sctx = {.app = &app};
420	    storage_prepare_stmt(&sctx);
421	    bus_subscribe(&app.bus, EVT_TRANSFORMED_RECORD, storage_cb, &sctx);
422	
423	    /* Dashboard */
424	    dash_ctx_t dctx = {.app = &app};
425	    if (app.dashboard_enabled) {
426	        initscr();
427	        noecho();
428	        cbreak();
429	        curs_set(FALSE);
430	        bus_subscribe(&app.bus, EVT_RECORD_INGESTED,    dashboard_cb, &dctx);
431	        bus_subscribe(&app.bus, EVT_VALID_RECORD,       dashboard_cb, &dctx);
432	        bus_subscribe(&app.bus, EVT_INVALID_RECORD,     dashboard_cb, &dctx);
433	        bus_subscribe(&app.bus, EVT_TRANSFORMED_RECORD, dashboard_cb, &dctx);
434	        dashboard_render(&dctx);
435	    }
436	
437	    /* ───── Ingest ───── */
438	    FILE *fp = strcmp(input_path, "-") == 0 ? stdin : fopen(input_path, "r");
439	    if (!fp) fatal("fopen input");
440	
441	    ingest_stream(fp, &app);
442	    if (fp != stdin) fclose(fp);
443	
444	    /* ───── Tear-down ───── */
445	    if (app.dashboard_enabled) {
446	        getch();
447	        endwin();
448	    }
449	
450	    sqlite3_finalize(sctx.stmt_insert);
451	    sqlite3_close(app.db);
452	    return 0;
453	}

1	/**
2	 * ingestion.c
3	 * StreamScoop Utility Lake - Data ingestion implementation.
4	 *
5	 * This module is responsible for acquiring streaming records from a variety
6	 * of sources (files, pipes, sockets, HTTP endpoints) and pushing them onto the
7	 * global event bus.  Each data line is forwarded as an INGEST_EVENT which
8	 * carries a monotonic sequence number, a capture timestamp (µs) and the raw
9	 * bytes (zero-terminated).
10	 *
11	 * The implementation is resilient: it supports automatic reconnection with
12	 * exponential back-off for remote sources, rate-limits error logs, and keeps
13	 * lightweight runtime metrics so the UI layer can display current ingest
14	 * status.
15	 */
16	
17	#include "config.h"             /* project-wide build options              */
18	#include "ingestion.h"          /* public API for the ingestion subsystem   */
19	#include "event_bus.h"          /* simple pub-sub API used by all modules   */
20	#include "logging.h"            /* tiny syslog-style wrapper                */
21	#include "metrics.h"            /* runtime counters exported to dashboard   */
22	
23	#include <stdio.h>
24	#include <stdlib.h>
25	#include <string.h>
26	#include <errno.h>
27	#include <inttypes.h>
28	#include <time.h>
29	#include <pthread.h>
30	#include <unistd.h>
31	#include <sys/stat.h>
32	#include <sys/types.h>
33	
34	#ifdef HAVE_LIBCURL
35	#include <curl/curl.h>
36	#endif
37	
38	/* ------------------------------------------------------------------------- */
39	/*                               constants                                   */
40	/* ------------------------------------------------------------------------- */
41	
42	#define INGEST_BUF_SZ      4096               /* read buffer size            */
43	#define RECONNECT_BASE_MS  500                /* initial reconnect delay     */
44	#define RECONNECT_MAX_MS   30 * 1000          /* cap when backing off        */
45	#define FILENAME_MAX_CHARS 1024
46	
47	/* ------------------------------------------------------------------------- */
48	/*                        internal helper structures                         */
49	/* ------------------------------------------------------------------------- */
50	
51	/* Represent a single ingest source (file, stdin, or network stream) */
52	typedef enum {
53	    SRC_FILE,
54	    SRC_STDIN,
55	    SRC_HTTP
56	} ingest_source_type_t;
57	
58	typedef struct ingest_source_s {
59	    ingest_source_type_t type;
60	    char                 identifier[FILENAME_MAX_CHARS]; /* path or URL */
61	    union {
62	        FILE    *fp;   /* file / stdin */
63	#ifdef HAVE_LIBCURL
64	        CURL    *curl; /* network */
65	#endif
66	    } handle;
67	} ingest_source_t;
68	
69	typedef struct ingestion_ctx_s {
70	    ingest_source_t   source;
71	    volatile int      should_stop;
72	    pthread_t         thread;
73	    uint64_t          seq_no;
74	    metric_counter_t *m_records_ok;
75	    metric_counter_t *m_records_err;
76	} ingestion_ctx_t;
77	
78	/* ------------------------------------------------------------------------- */
79	/*                      forward declarations & locals                        */
80	/* ------------------------------------------------------------------------- */
81	
82	static void        *ingest_thread_main(void *arg);
83	static int          ingest_open_source(ingest_source_t *src);
84	static void         ingest_close_source(ingest_source_t *src);
85	static size_t       http_write_cb(char *ptr, size_t size, size_t nmemb, void *userdata);
86	static int          publish_line(const char *line, size_t len, ingestion_ctx_t *ctx);
87	static uint64_t     now_epoch_us(void);
88	static void         backoff_sleep(unsigned *attempt);
89	
90	/* ------------------------------------------------------------------------- */
91	/*                         public API implementation                         */
92	/* ------------------------------------------------------------------------- */
93	
94	ingestion_handle_t *ingestion_start(const char *uri)
95	{
96	    ingestion_ctx_t *ctx = calloc(1, sizeof(*ctx));
97	    if (!ctx) {
98	        LOGE("ingestion: out of memory");
99	        return NULL;
100	    }
101	
102	    /* Setup metrics. Dashboard will pick them up later. */
103	    ctx->m_records_ok  = metrics_counter_create("ingest.records_ok");
104	    ctx->m_records_err = metrics_counter_create("ingest.records_err");
105	
106	    /* Detect source type from URI */
107	    if (!uri || strcmp(uri, "-") == 0) {
108	        ctx->source.type = SRC_STDIN;
109	        strncpy(ctx->source.identifier, "stdin", sizeof(ctx->source.identifier));
110	    } else if (strncasecmp(uri, "http://", 7) == 0 ||
111	               strncasecmp(uri, "https://", 8) == 0) {
112	        ctx->source.type = SRC_HTTP;
113	        strncpy(ctx->source.identifier, uri, sizeof(ctx->source.identifier));
114	    } else {
115	        ctx->source.type = SRC_FILE;
116	        strncpy(ctx->source.identifier, uri, sizeof(ctx->source.identifier));
117	    }
118	
119	    if (pthread_create(&ctx->thread, NULL, ingest_thread_main, ctx) != 0) {
120	        LOGE("ingestion: failed to spawn thread: %s", strerror(errno));
121	        free(ctx);
122	        return NULL;
123	    }
124	
125	    LOGI("ingestion: started for source '%s'", ctx->source.identifier);
126	    return (ingestion_handle_t *)ctx;
127	}
128	
129	void ingestion_stop(ingestion_handle_t *handle)
130	{
131	    if (!handle) return;
132	    ingestion_ctx_t *ctx = (ingestion_ctx_t *)handle;
133	    ctx->should_stop = 1;
134	    pthread_join(ctx->thread, NULL);
135	    metrics_counter_destroy(ctx->m_records_ok);
136	    metrics_counter_destroy(ctx->m_records_err);
137	    free(ctx);
138	}
139	
140	/* ------------------------------------------------------------------------- */
141	/*                            thread function                                */
142	/* ------------------------------------------------------------------------- */
143	
144	static void *ingest_thread_main(void *arg)
145	{
146	    ingestion_ctx_t *ctx = arg;
147	    unsigned backoff_attempt = 0;
148	
149	#ifdef HAVE_LIBCURL
150	    CURLcode cr;
151	    if (ctx->source.type == SRC_HTTP) {
152	        curl_global_init(CURL_GLOBAL_ALL);
153	    }
154	#endif
155	
156	    while (!ctx->should_stop) {
157	        if (ingest_open_source(&ctx->source) != 0) {
158	            /* open failed, wait and retry with back-off */
159	            backoff_sleep(&backoff_attempt);
160	            continue;
161	        }
162	        backoff_attempt = 0; /* reset on success */
163	
164	        char buf[INGEST_BUF_SZ];
165	        size_t len = 0;
166	
167	        /* two code paths: FILE* or CURL streaming */
168	        if (ctx->source.type == SRC_HTTP) {
169	#ifdef HAVE_LIBCURL
170	            /* For HTTP streaming, libcurl will push data to our callback which will in turn
171	             * publish events. Here we just perform() until it returns or stop requested. */
172	            CURL *curl = ctx->source.handle.curl;
173	            while (!ctx->should_stop &&
174	                   (cr = curl_easy_perform(curl)) == CURLE_OK) {
175	                /* libcurl will keep calling http_write_cb. We loop until stop or error. */
176	            }
177	            if (cr != CURLE_OK && !ctx->should_stop) {
178	                LOGW("ingestion: curl_easy_perform stopped: %s", curl_easy_strerror(cr));
179	            }
180	#endif
181	        } else { /* FILE or STDIN */
182	            FILE *fp = ctx->source.handle.fp;
183	            while (!ctx->should_stop && fgets(buf, sizeof(buf), fp) != NULL) {
184	                len = strnlen(buf, sizeof(buf));
185	                if (publish_line(buf, len, ctx) != 0) {
186	                    /* publish failed; count but keep going */
187	                    metrics_counter_inc(ctx->m_records_err);
188	                } else {
189	                    metrics_counter_inc(ctx->m_records_ok);
190	                }
191	            }
192	
193	            if (!ctx->should_stop && ferror(fp)) {
194	                LOGW("ingestion: read error on %s: %s",
195	                     ctx->source.identifier, strerror(errno));
196	            }
197	        }
198	
199	        ingest_close_source(&ctx->source);
200	
201	        if (!ctx->should_stop) {
202	            /* auto-reconnect after short delay */
203	            LOGI("ingestion: reconnecting to %s", ctx->source.identifier);
204	            backoff_sleep(&backoff_attempt);
205	        }
206	    }
207	
208	#ifdef HAVE_LIBCURL
209	    if (ctx->source.type == SRC_HTTP) {
210	        curl_global_cleanup();
211	    }
212	#endif
213	
214	    return NULL;
215	}
