289	/* ------------------------------------------------------------------------- */
290	/*                libcurl write callback (HTTP streaming mode)               */
291	/* ------------------------------------------------------------------------- */
292	
293	static size_t http_write_cb(char *ptr, size_t size, size_t nmemb, void *userdata)
294	{
295	    ingest_source_t *src = userdata;
296	    ingestion_ctx_t *ctx = (ingestion_ctx_t *)((char *)src - offsetof(ingestion_ctx_t, source));
297	
298	    size_t total = size * nmemb;
299	    const char *p = ptr;
300	    const char *end = ptr + total;
301	
302	    /* Process complete lines; keep remainder in static buffer per ctx */
303	    static __thread char linebuf[INGEST_BUF_SZ];
304	    static __thread size_t linepos = 0;
305	
306	    while (p < end) {
307	        char c = *p++;
308	        if (c == '\n' || c == '\r') {
309	            /* finalize line */
310	            linebuf[linepos] = '\0';
311	            if (linepos > 0) {
312	                if (publish_line(linebuf, linepos, ctx) != 0)
313	                    metrics_counter_inc(ctx->m_records_err);
314	                else
315	                    metrics_counter_inc(ctx->m_records_ok);
316	            }
317	            linepos = 0;
318	        } else if (linepos < sizeof(linebuf) - 1) {
319	            linebuf[linepos++] = c;
320	        } else {
321	            /* line too long, drop */
322	            LOGW("ingestion: line truncated (>%zu bytes)", sizeof(linebuf));
323	            linepos = 0;
324	        }
325	    }
326	
327	    return total;
328	}
