1	#include "event_bus.h"
2	/*
3	 * StreamScoop Utility Lake – internal event bus implementation.
4	 *
5	 * The event bus provides an asynchronous publish/subscribe mechanism so that
6	 * ingestion, validation, transformation, storage, and UI layers can communicate
7	 * without compile-time coupling.  A single dispatcher thread drains a
8	 * multi-producer queue and fan-outs events to interested subscribers.
9	 *
10	 * Author: StreamScoop Engineering
11	 * License: MIT (see LICENSE file)
12	 */
13	
14	#include <errno.h>
15	#include <pthread.h>
16	#include <stdbool.h>
17	#include <stdint.h>
18	#include <stdio.h>
19	#include <stdlib.h>
20	#include <string.h>
21	#include <time.h>
22	#include <unistd.h>
