24	/* -------------------------------------------------------------------------- */
25	/*                              Public interface                              */
26	/* -------------------------------------------------------------------------- */
27	
28	/*
29	 * If your build does not provide event_bus.h yet, you can temporarily include
30	 * the forward declarations below.  The actual header shipped with the library
31	 * contains identical definitions.
32	 */
33	#ifndef STREAMSCOOP_EVENT_BUS_H
34	#define STREAMSCOOP_EVENT_BUS_H
35	
36	typedef enum {
37	    EV_INGEST_LINE = 0,      /* char* – raw CSV/JSON text line                     */
38	    EV_VALIDATION_RESULT,    /* struct validation_result*                          */
39	    EV_TRANSFORM_RESULT,     /* struct transform_result*                           */
40	    EV_STORAGE_WRITE,        /* struct storage_ack*                                */
41	    EV_UI_COMMAND,           /* struct ui_cmd*                                     */
42	    EV_SHUTDOWN_SIGNAL,      /* NULL – broadcast when the application is stopping  */
43	
44	    EV__COUNT               /* sentinel – must be last                             */
45	} event_type_t;
46	
47	/* Callback signature for subscribers. */
48	typedef void (*event_cb_t)(event_type_t type, const void *payload, void *userdata);
49	
50	/* Opaque handles for subscriptions. */
51	typedef int32_t event_subscriber_t;
52	
53	/* Event-bus lifecycle. */
54	int  event_bus_init(void);
55	void event_bus_shutdown(void);
56	
57	/* Publish/subscribe API. */
58	event_subscriber_t event_bus_subscribe(event_type_t type,
59	                                       event_cb_t     cb,
60	                                       void          *userdata);
61	void               event_bus_unsubscribe(event_subscriber_t handle);
62	int                event_bus_publish(event_type_t  type,
63	                                     void         *payload,
64	                                     void        (*destructor)(void *));
65	#endif /* STREAMSCOOP_EVENT_BUS_H */
66	
67	/* -------------------------------------------------------------------------- */
68	/*                            Internal implementation                          */
69	/* -------------------------------------------------------------------------- */
70	
71	/* --- Compile-time tunables ------------------------------------------------- */
72	#define BUS_MAX_SUBSCRIBERS   1024      /* Hard cap to guard accidental leaks  */
73	#define BUS_QUEUE_HIGH_WATER  16384     /* Back-pressure level                 */
74	#define BUS_QUEUE_LOW_WATER   1024      /* Resume publishing after throttling  */
75	
76	/* --- Data structures ------------------------------------------------------- */
77	typedef struct bus_subscriber {
78	    event_subscriber_t id;
79	    event_cb_t         cb;
80	    void              *userdata;
81	    bool               active;
82	    struct bus_subscriber *next;
83	} bus_subscriber_t;
84	
85	typedef struct bus_event {
86	    event_type_t  type;
87	    void         *payload;
88	    void        (*destructor)(void *);
89	    struct bus_event *next;
90	} bus_event_t;
91	
92	typedef struct {
93	    /* Subscriber registry */
94	    bus_subscriber_t *subs[EV__COUNT];
95	    int32_t           next_sub_id;
96	
97	    /* Event queue */
98	    bus_event_t      *q_head;
99	    bus_event_t      *q_tail;
100	    size_t            q_len;
101	
102	    /* Synchronisation primitives */
103	    pthread_mutex_t   lock;
104	    pthread_cond_t    cond_non_empty;
105	    pthread_cond_t    cond_low_water;
106	
107	    /* Lifecycle */
108	    bool              running;
109	    pthread_t         dispatcher_tid;
110	} event_bus_t;
111	
112	/* Global singleton – because the tool is a single, small binary. */
113	static event_bus_t G_BUS = {
114	    .subs             = {NULL},
115	    .next_sub_id      = 1,
116	    .q_head           = NULL,
117	    .q_tail           = NULL,
118	    .q_len            = 0,
119	    .lock             = PTHREAD_MUTEX_INITIALIZER,
120	    .cond_non_empty   = PTHREAD_COND_INITIALIZER,
121	    .cond_low_water   = PTHREAD_COND_INITIALIZER,
122	    .running          = false,
123	    .dispatcher_tid   = (pthread_t)0
124	};
125	
126	/* --- Logging helper -------------------------------------------------------- */
127	static void bus_log(const char *lvl, const char *fmt, ...)
128	{
129	    va_list ap;
130	    va_start(ap, fmt);
131	    fprintf(stderr, "[%s] ", lvl);
132	    vfprintf(stderr, fmt, ap);
133	    fprintf(stderr, "\n");
134	    fflush(stderr);
135	    va_end(ap);
136	}
137	
138	/* --- Utility ----------------------------------------------------------------*/
139	static bus_event_t *event_node_new(event_type_t type,
140	                                   void        *payload,
141	                                   void       (*destructor)(void *))
142	{
143	    bus_event_t *ev = (bus_event_t *)calloc(1, sizeof *ev);
144	    if (!ev) {
145	        return NULL;
146	    }
147	    ev->type       = type;
148	    ev->payload    = payload;
149	    ev->destructor = destructor;
150	    ev->next       = NULL;
151	    return ev;
152	}
153	
154	/* --- Dispatcher thread ----------------------------------------------------- */
155	static void *dispatcher_main(void *arg)
156	{
157	    (void)arg;
158	    event_bus_t *bus = &G_BUS;
159	
160	    pthread_mutex_lock(&bus->lock);
161	    while (bus->running) {
162	        while (bus->q_head == NULL && bus->running) {
163	            pthread_cond_wait(&bus->cond_non_empty, &bus->lock);
164	        }
165	        if (!bus->running) {
166	            break;
167	        }
168	        /* Pop event */
169	        bus_event_t *ev = bus->q_head;
170	        bus->q_head = ev->next;
171	        if (!bus->q_head) {
172	            bus->q_tail = NULL;
173	        }
174	        bus->q_len--;
175	        if (bus->q_len < BUS_QUEUE_LOW_WATER) {
176	            pthread_cond_broadcast(&bus->cond_low_water);
177	        }
178	        pthread_mutex_unlock(&bus->lock);
179	
180	        /* Fan-out to subscribers */
181	        pthread_mutex_lock(&bus->lock);
182	        bus_subscriber_t *sub = bus->subs[ev->type];
183	        while (sub) {
184	            if (sub->active) {
185	                /* Release lock during callback to prevent deadlocks */
186	                pthread_mutex_unlock(&bus->lock);
187	                sub->cb(ev->type, ev->payload, sub->userdata);
188	                pthread_mutex_lock(&bus->lock);
189	            }
190	            sub = sub->next;
191	        }
192	        pthread_mutex_unlock(&bus->lock);
193	
194	        /* Clean up event payload after subscribers have processed it. */
195	        if (ev->destructor) {
196	            ev->destructor(ev->payload);
197	        }
198	        free(ev);
199	
200	        pthread_mutex_lock(&bus->lock);
201	    }
202	    pthread_mutex_unlock(&bus->lock);
203	    return NULL;
204	}
205	
206	/* --- Public API implementation -------------------------------------------- */
207	int event_bus_init(void)
208	{
209	    event_bus_t *bus = &G_BUS;
210	    if (bus->running) {
211	        return 0; /* Already initialised */
212	    }
213	    bus->running = true;
214	
215	    int rc = pthread_create(&bus->dispatcher_tid, NULL, dispatcher_main, NULL);
216	    if (rc != 0) {
217	        bus_log("ERROR", "Failed to start dispatcher thread: %s", strerror(rc));
218	        bus->running = false;
219	        return -1;
220	    }
221	    return 0;
222	}
223	
224	void event_bus_shutdown(void)
225	{
226	    event_bus_t *bus = &G_BUS;
227	    if (!bus->running) {
228	        return;
229	    }
230	
231	    /* Publish shutdown signal so listeners can clean up. */
232	    event_bus_publish(EV_SHUTDOWN_SIGNAL, NULL, NULL);
233	
234	    pthread_mutex_lock(&bus->lock);
235	    bus->running = false;
236	    pthread_cond_broadcast(&bus->cond_non_empty);
237	    pthread_mutex_unlock(&bus->lock);
238	
239	    /* Join dispatcher */
240	    pthread_join(bus->dispatcher_tid, NULL);
241	
242	    /* Drain queue (should be empty, but be defensive). */
243	    pthread_mutex_lock(&bus->lock);
244	    while (bus->q_head) {
245	        bus_event_t *ev = bus->q_head;
246	        bus->q_head = ev->next;
247	        if (ev->destructor) {
248	            ev->destructor(ev->payload);
249	        }
250	        free(ev);
251	    }
252	    pthread_mutex_unlock(&bus->lock);
253	
254	    /* Free subscriber lists */
255	    for (int i = 0; i < EV__COUNT; ++i) {
256	        bus_subscriber_t *sub = bus->subs[i];
257	        while (sub) {
258	            bus_subscriber_t *next = sub->next;
259	            free(sub);
260	            sub = next;
261	        }
262	        bus->subs[i] = NULL;
263	    }
264	    bus->q_tail = bus->q_head = NULL;
265	    bus->q_len  = 0;
266	    bus->next_sub_id = 1;
267	}
268	
269	static bus_subscriber_t *find_sub_by_id(event_bus_t *bus, event_subscriber_t id,
270	                                        int *out_index)
271	{
272	    for (int i = 0; i < EV__COUNT; ++i) {
273	        bus_subscriber_t *sub = bus->subs[i];
274	        while (sub) {
275	            if (sub->id == id) {
276	                if (out_index) {
277	                    *out_index = i;
278	                }
279	                return sub;
280	            }
281	            sub = sub->next;
282	        }
283	    }
284	    return NULL;
285	}
286	
287	event_subscriber_t event_bus_subscribe(event_type_t type,
288	                                       event_cb_t    cb,
289	                                       void         *userdata)
290	{
291	    if (type >= EV__COUNT || !cb) {
292	        errno = EINVAL;
293	        return -1;
294	    }
295	
296	    event_bus_t *bus = &G_BUS;
297	    pthread_mutex_lock(&bus->lock);
298	
299	    if (bus->next_sub_id >= BUS_MAX_SUBSCRIBERS) {
300	        pthread_mutex_unlock(&bus->lock);
301	        errno = ENOSPC;
302	        return -1;
303	    }
304	
305	    bus_subscriber_t *sub = (bus_subscriber_t *)calloc(1, sizeof *sub);
306	    if (!sub) {
307	        pthread_mutex_unlock(&bus->lock);
308	        errno = ENOMEM;
309	        return -1;
310	    }
311	    sub->id       = bus->next_sub_id++;
312	    sub->cb       = cb;
313	    sub->userdata = userdata;
314	    sub->active   = true;
315	    sub->next     = bus->subs[type];
316	    bus->subs[type] = sub;
317	
318	    pthread_mutex_unlock(&bus->lock);
319	    return sub->id;
320	}
321	
322	void event_bus_unsubscribe(event_subscriber_t handle)
323	{
324	    if (handle <= 0) {
325	        return;
326	    }
327	    event_bus_t *bus = &G_BUS;
328	    pthread_mutex_lock(&bus->lock);
329	
330	    int idx = -1;
331	    bus_subscriber_t *sub = find_sub_by_id(bus, handle, &idx);
332	    if (!sub) {
333	        pthread_mutex_unlock(&bus->lock);
334	        return;
335	    }
336	    /* Mark inactive; will be cleaned up later. */
337	    sub->active = false;
338	
339	    /* Remove from list now to free memory promptly. */
340	    bus_subscriber_t **head = &bus->subs[idx];
341	    bus_subscriber_t *prev = NULL, *cur = *head;
342	    while (cur) {
343	        if (cur == sub) {
344	            if (prev) {
345	                prev->next = cur->next;
346	            } else {
347	                *head = cur->next;
348	            }
349	            free(cur);
350	            break;
351	        }
352	        prev = cur;
353	        cur  = cur->next;
354	    }
355	
356	    pthread_mutex_unlock(&bus->lock);
357	}
358	
359	int event_bus_publish(event_type_t type,
360	                      void        *payload,
361	                      void       (*destructor)(void *))
362	{
363	    if (type >= EV__COUNT) {
364	        errno = EINVAL;
365	        return -1;
366	    }
367	
368	    event_bus_t *bus = &G_BUS;
369	    bus_event_t *ev = event_node_new(type, payload, destructor);
370	    if (!ev) {
371	        errno = ENOMEM;
372	        return -1;
373	    }
374	
375	    pthread_mutex_lock(&bus->lock);
376	
377	    /* Back-pressure: block if queue is too large. */
378	    while (bus->q_len >= BUS_QUEUE_HIGH_WATER) {
379	        pthread_cond_wait(&bus->cond_low_water, &bus->lock);
380	    }
381	
382	    /* Push */
383	    if (!bus->q_tail) {
384	        bus->q_head = bus->q_tail = ev;
385	    } else {
386	        bus->q_tail->next = ev;
387	        bus->q_tail       = ev;
388	    }
389	    bus->q_len++;
390	
391	    pthread_cond_signal(&bus->cond_non_empty);
392	    pthread_mutex_unlock(&bus->lock);
393	    return 0;
394	}
