142	
143	/*
144	 * Subscribe to pipeline events. Returns an observer ID that can
145	 * later be used to unregister.
146	 */
147	unsigned long processing_observer_register(event_cb_t cb, void *user_data)
148	{
149	    if (!cb) return 0;
150	
151	    pthread_mutex_lock(&g_ctx.obs_mtx);
152	
153	    /* Expand storage if necessary */
154	    if (g_ctx.obs_len >= g_ctx.obs_cap) {
155	        size_t new_cap = g_ctx.obs_cap ? g_ctx.obs_cap * ARRAY_GROW_FACTOR
156	                                       : INITIAL_ARRAY_CAP;
157	        observer_t *tmp = realloc(g_ctx.observers, new_cap * sizeof(observer_t));
158	        if (!tmp) {
159	            pthread_mutex_unlock(&g_ctx.obs_mtx);
160	            return 0;
161	        }
162	        g_ctx.observers = tmp;
163	        g_ctx.obs_cap   = new_cap;
164	    }
165	
166	    unsigned long id = g_ctx.next_id++;
167	    g_ctx.observers[g_ctx.obs_len++] = (observer_t){ .id = id, .cb = cb, .user = user_data };
168	
169	    pthread_mutex_unlock(&g_ctx.obs_mtx);
170	    return id;
171	}
172	
173	void processing_observer_unregister(unsigned long id)
174	{
175	    pthread_mutex_lock(&g_ctx.obs_mtx);
176	
177	    for (size_t i = 0; i < g_ctx.obs_len; ++i) {
178	        if (g_ctx.observers[i].id == id) {
179	            /* Remove by shifting tail */
180	            memmove(&g_ctx.observers[i],
181	                    &g_ctx.observers[i + 1],
182	                    (g_ctx.obs_len - i - 1) * sizeof(observer_t));
183	            g_ctx.obs_len--;
184	            break;
185	        }
186	    }
187	
188	    pthread_mutex_unlock(&g_ctx.obs_mtx);
189	}
190	
191	static void dispatch_event(const event_t *evt)
192	{
193	    pthread_mutex_lock(&g_ctx.obs_mtx);
194	    for (size_t i = 0; i < g_ctx.obs_len; ++i) {
195	        g_ctx.observers[i].cb(evt, g_ctx.observers[i].user);
196	    }
197	    pthread_mutex_unlock(&g_ctx.obs_mtx);
198	}
