203	
204	static field_type_t str_to_field_type(const char *s)
205	{
206	    if (!s) return FIELD_UNKNOWN;
207	    if (strcasecmp(s, "string") == 0) return FIELD_STRING;
208	    if (strcasecmp(s, "int")    == 0) return FIELD_INT;
209	    if (strcasecmp(s, "float")  == 0) return FIELD_FLOAT;
210	    if (strcasecmp(s, "bool")   == 0) return FIELD_BOOL;
211	    return FIELD_UNKNOWN;
212	}
213	
214	static bool compile_schema(const char *schema_json, schema_t *out, char **err_out)
215	{
216	    *err_out = NULL;
217	    cJSON *root = cJSON_Parse(schema_json);
218	    if (!root) {
219	        asprintf(err_out, "Failed to parse schema JSON");
220	        return false;
221	    }
222	
223	    if (!cJSON_IsArray(root)) {
224	        asprintf(err_out, "Schema root must be an array");
225	        cJSON_Delete(root);
226	        return false;
227	    }
228	
229	    size_t count = cJSON_GetArraySize(root);
230	    if (count == 0) {
231	        asprintf(err_out, "Schema array is empty");
232	        cJSON_Delete(root);
233	        return false;
234	    }
235	
236	    schema_field_t *fields = calloc(count, sizeof(schema_field_t));
237	    if (!fields) {
238	        cJSON_Delete(root);
239	        asprintf(err_out, "Out of memory");
240	        return false;
241	    }
242	
243	    size_t idx = 0;
244	    bool ok = true;
245	
246	    cJSON *item = NULL;
247	    cJSON_ArrayForEach(item, root) {
248	        cJSON *name = cJSON_GetObjectItemCaseSensitive(item, "name");
249	        cJSON *type = cJSON_GetObjectItemCaseSensitive(item, "type");
250	        if (!cJSON_IsString(name) || !cJSON_IsString(type)) {
251	            asprintf(err_out, "Each schema element must have string 'name' and 'type'");
252	            ok = false;
253	            break;
254	        }
255	
256	        fields[idx].name = strdup(name->valuestring);
257	        fields[idx].type = str_to_field_type(type->valuestring);
258	        if (fields[idx].type == FIELD_UNKNOWN) {
259	            asprintf(err_out, "Unsupported type '%s' for field '%s'",
260	                     type->valuestring, name->valuestring);
261	            ok = false;
262	            break;
263	        }
264	        idx++;
265	    }
266	
267	    if (!ok) {
268	        for (size_t i = 0; i < idx; ++i) free(fields[i].name);
269	        free(fields);
270	        cJSON_Delete(root);
271	        return false;
272	    }
273	
274	    out->fields = fields;
275	    out->count  = count;
276	
277	    cJSON_Delete(root);
278	    return true;
279	}
280	
281	static void free_schema(schema_t *s)
282	{
283	    if (!s || !s->fields) return;
284	    for (size_t i = 0; i < s->count; ++i) free(s->fields[i].name);
285	    free(s->fields);
286	    s->fields = NULL;
287	    s->count  = 0;
288	}
