290	/* **********************************************************************
291	 *                         Line parsing helpers
292	 * *********************************************************************/
293	
294	static inline void skip_whitespace(const char **p)
295	{
296	    while (**p && isspace((unsigned char)**p)) (*p)++;
297	}
298	
299	static bool parse_csv_line(const char *line, record_t *out_rec, char **err_out)
300	{
301	    *err_out = NULL;
302	    size_t cap = 8, cnt = 0;
303	    char **fields = calloc(cap, sizeof(char*));
304	    if (!fields) {
305	        asprintf(err_out, "Out of memory");
306	        return false;
307	    }
308	
309	    const char *p = line;
310	    while (*p) {
311	        skip_whitespace(&p);
312	        bool quoted = false;
313	        if (*p == '"') { quoted = true; p++; }
314	
315	        const char *start = p;
316	        char *field = NULL;
317	        size_t len = 0;
318	
319	        while (*p) {
320	            if (quoted) {
321	                if (*p == '"' && *(p+1) != '"') break;
322	                if (*p == '"' && *(p+1) == '"') { p++; } /* skip escaped quote */
323	            } else if (*p == ',') break;
324	            p++;
325	        }
326	        len = p - start;
327	        field = malloc(len + 1);
328	        if (!field) {
329	            asprintf(err_out, "Out of memory");
330	            goto fail;
331	        }
332	        memcpy(field, start, len);
333	        field[len] = 0;
334	
335	        /* replace double quotes with single inside quoted fields */
336	        if (quoted) {
337	            char *dst = field, *src = field;
338	            while (*src) {
339	                if (*src == '"' && *(src+1) == '"') src++; /* skip first quote */
340	                *dst++ = *src++;
341	            }
342	            *dst = '\0';
343	        }
344	
345	        if (cnt >= cap) {
346	            cap *= ARRAY_GROW_FACTOR;
347	            char **tmp = realloc(fields, cap * sizeof(char*));
348	            if (!tmp) {
349	                asprintf(err_out, "Out of memory");
350	                free(field);
351	                goto fail;
352	            }
353	            fields = tmp;
354	        }
355	        fields[cnt++] = field;
356	
357	        if (quoted && *p == '"') p++;
358	        if (*p == ',') p++;
359	    }
360	
361	    out_rec->fields = fields;
362	    out_rec->field_count = cnt;
363	    return true;
364	
365	fail:
366	    for (size_t i = 0; i < cnt; ++i) free(fields[i]);
367	    free(fields);
368	    return false;
369	}
370	
371	static bool parse_json_line(const char *line, record_t *out_rec, char **err_out)
372	{
373	    *err_out = NULL;
374	    cJSON *root = cJSON_Parse(line);
375	    if (!root) {
376	        asprintf(err_out, "Invalid JSON");
377	        return false;
378	    }
379	    if (!cJSON_IsObject(root)) {
380	        asprintf(err_out, "JSON root must be an object");
381	        cJSON_Delete(root);
382	        return false;
383	    }
384	
385	    size_t field_cnt = cJSON_GetArraySize(root);
386	    char **fields = calloc(field_cnt, sizeof(char*));
387	    if (!fields) {
388	        asprintf(err_out, "Out of memory");
389	        cJSON_Delete(root);
390	        return false;
391	    }
392	
393	    size_t idx = 0;
394	    cJSON *item = NULL;
395	    cJSON_ArrayForEach(item, root) {
396	        /* Serialize primitive value to string */
397	        if (cJSON_IsString(item)) {
398	            fields[idx++] = strdup(item->valuestring);
399	        } else if (cJSON_IsNumber(item)) {
400	            asprintf(&fields[idx++], "%g", item->valuedouble);
401	        } else if (cJSON_IsBool(item)) {
402	            fields[idx++] = strdup(cJSON_IsTrue(item) ? "true" : "false");
403	        } else {
404	            fields[idx++] = strdup(""); /* unsupported type -> empty string */
405	        }
406	    }
407	
408	    out_rec->fields = fields;
409	    out_rec->field_count = field_cnt;
410	
411	    cJSON_Delete(root);
412	    return true;
413	}
414	
415	static bool parse_line(const char *line, record_t *out_rec, char **err_out)
416	{
417	    const char *p = line;
418	    skip_whitespace(&p);
419	    if (*p == '{' || *p == '[') {
420	        return parse_json_line(line, out_rec, err_out);
421	    }
422	    return parse_csv_line(line, out_rec, err_out);
423	}
