425	/* **********************************************************************
426	 *                         Record utilities
427	 * *********************************************************************/
428	
429	static void free_record(record_t *rec)
430	{
431	    if (!rec || !rec->fields) return;
432	    for (size_t i = 0; i < rec->field_count; ++i) free(rec->fields[i]);
433	    free(rec->fields);
434	    rec->fields = NULL;
435	    rec->field_count = 0;
436	}
437	
438	/* **********************************************************************
439	 *                         Validation
440	 * *********************************************************************/
441	
442	static bool validate_int(const char *s)
443	{
444	    if (!s || !*s) return false;
445	    if (*s == '+' || *s == '-') s++;
446	    while (*s && isdigit((unsigned char)*s)) s++;
447	    return *s == '\0';
448	}
449	
450	static bool validate_float(const char *s)
451	{
452	    if (!s || !*s) return false;
453	    char *end = NULL;
454	    strtod(s, &end);
455	    return end && *end == '\0';
456	}
457	
458	static bool validate_bool(const char *s)
459	{
460	    return s && (strcasecmp(s, "true") == 0 ||
461	                 strcasecmp(s, "false") == 0 ||
462	                 strcmp(s, "0") == 0 ||
463	                 strcmp(s, "1") == 0);
464	}
465	
466	static bool validate_record(const record_t *rec, const schema_t *s, char **err_out)
467	{
468	    *err_out = NULL;
469	    if (rec->field_count != s->count) {
470	        asprintf(err_out, "Field count mismatch: expected %zu, got %zu",
471	                 s->count, rec->field_count);
472	        return false;
473	    }
474	
475	    for (size_t i = 0; i < s->count; ++i) {
476	        const char *val = rec->fields[i];
477	        switch (s->fields[i].type) {
478	            case FIELD_STRING:
479	                /* always valid */
480	                break;
481	            case FIELD_INT:
482	                if (!validate_int(val)) {
483	                    asprintf(err_out, "Field '%s' value '%s' not int",
484	                             s->fields[i].name, val);
485	                    return false;
486	                }
487	                break;
488	            case FIELD_FLOAT:
489	                if (!validate_float(val)) {
490	                    asprintf(err_out, "Field '%s' value '%s' not float",
491	                             s->fields[i].name, val);
492	                    return false;
493	                }
494	                break;
495	            case FIELD_BOOL:
496	                if (!validate_bool(val)) {
497	                    asprintf(err_out, "Field '%s' value '%s' not bool",
498	                             s->fields[i].name, val);
499	                    return false;
500	                }
501	                break;
502	            default:
503	                asprintf(err_out, "Unsupported field type");
504	                return false;
505	        }
506	    }
507	    return true;
508	}
509	
510	/* **********************************************************************
511	 *                         Transformation
512	 * *********************************************************************/
513	
514	/*
515	 * Very basic transformation example:
516	 *  - ints are multiplied by 2
517	 *  - strings converted to uppercase
518	 */
519	static void transform_record(record_t *rec)
520	{
521	    for (size_t i = 0; i < rec->field_count; ++i) {
522	        /* Try integer */
523	        char *end = NULL;
524	        long val = strtol(rec->fields[i], &end, 10);
525	        if (end && *end == '\0') {
526	            /* integer */
527	            val *= 2;
528	            free(rec->fields[i]);
529	            asprintf(&rec->fields[i], "%ld", val);
530	            continue;
531	        }
532	
533	        /* Else uppercase the string */
534	        for (char *p = rec->fields[i]; *p; ++p) *p = (char)toupper((unsigned char)*p);
535	    }
536	}
