538	/* **********************************************************************
539	 *                         SQLite helpers
540	 * *********************************************************************/
541	
542	static void sqlite_log(void *unused, int err_code, const char *msg)
543	{
544	    UNUSED(unused);
545	    LOG_DBG("SQLite (%d): %s", err_code, msg);
546	}
547	
548	static bool ensure_partition_table(sqlite3 *db, char **err_out)
549	{
550	    *err_out = NULL;
551	    time_t now = time(NULL);
552	    struct tm tm_now;
553	    localtime_r(&now, &tm_now);
554	
555	    char table[32];
556	    strftime(table, sizeof(table), "records_%Y%m%d", &tm_now);
557	
558	    char *sql;
559	    asprintf(&sql,
560	             "CREATE TABLE IF NOT EXISTS %s ("
561	             "id INTEGER PRIMARY KEY AUTOINCREMENT,"
562	             "ingest_ts DATETIME DEFAULT CURRENT_TIMESTAMP,"
563	             "payload TEXT NOT NULL);",
564	             table);
565	    char *errmsg = NULL;
566	    int rc = sqlite3_exec(db, sql, NULL, NULL, &errmsg);
567	    free(sql);
568	
569	    if (rc != SQLITE_OK) {
570	        asprintf(err_out, "SQLite error: %s", errmsg ? errmsg : "unknown");
571	        sqlite3_free(errmsg);
572	        return false;
573	    }
574	    return true;
575	}
576	
577	static bool store_record(sqlite3 *db, const record_t *rec, char **err_out)
578	{
579	    *err_out = NULL;
580	    if (!ensure_partition_table(db, err_out))
581	        return false;
582	
583	    time_t now = time(NULL);
584	    struct tm tm_now;
585	    localtime_r(&now, &tm_now);
586	
587	    char table[32];
588	    strftime(table, sizeof(table), "records_%Y%m%d", &tm_now);
589	
590	    /* Serialize record to JSON string for storage */
591	    cJSON *obj = cJSON_CreateObject();
592	    for (size_t i = 0; i < rec->field_count; ++i) {
593	        char key[16];
594	        snprintf(key, sizeof(key), "f%zu", i);
595	        cJSON_AddStringToObject(obj, key, rec->fields[i]);
596	    }
597	    char *json_str = cJSON_PrintUnformatted(obj);
598	    cJSON_Delete(obj);
599	    if (!json_str) {
600	        asprintf(err_out, "Unable to serialize record");
601	        return false;
602	    }
603	
604	    sqlite3_stmt *stmt = NULL;
605	    char *sql;
606	    asprintf(&sql, "INSERT INTO %s (payload) VALUES (?);", table);
607	    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
608	    free(sql);
609	    if (rc != SQLITE_OK) {
610	        asprintf(err_out, "SQLite prepare failed: %s", sqlite3_errmsg(db));
611	        free(json_str);
612	        return false;
613	    }
614	
615	    rc = sqlite3_bind_text(stmt, 1, json_str, -1, SQLITE_TRANSIENT);
616	    if (rc != SQLITE_OK) {
617	        asprintf(err_out, "SQLite bind error: %s", sqlite3_errmsg(db));
618	        sqlite3_finalize(stmt);
619	        free(json_str);
620	        return false;
621	    }
622	
623	    rc = sqlite3_step(stmt);
624	    if (rc != SQLITE_DONE) {
625	        asprintf(err_out, "SQLite step error: %s", sqlite3_errmsg(db));
626	        sqlite3_finalize(stmt);
627	        free(json_str);
628	        return false;
629	    }
630	
631	    sqlite3_finalize(stmt);
632	    free(json_str);
633	    return true;
634	}
