637	 *                         Public API
638	 * *********************************************************************/
639	
640	/*
641	 * Initialize processing pipeline.
642	 *
643	 * sqlite_path  – file path for SQLite DB (created if missing)
644	 * schema_json  – JSON description of expected record schema
645	 *
646	 * Returns true on success.
647	 */
648	bool processing_init(const char *sqlite_path,
649	                     const char *schema_json)
650	{
651	    char *err = NULL;
652	    if (g_ctx.ready) {
653	        LOG_ERR("processing already initialized");
654	        return false;
655	    }
656	
657	    /* Compile schema */
658	    if (!compile_schema(schema_json, &g_ctx.schema, &err)) {
659	        LOG_ERR("%s", err);
660	        free(err);
661	        goto fail;
662	    }
663	
664	    /* Open DB */
665	    if (sqlite3_open_v2(sqlite_path, &g_ctx.db,
666	                        SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE |
667	                        SQLITE_OPEN_FULLMUTEX, NULL) != SQLITE_OK) {
668	        LOG_ERR("Cannot open SQLite '%s': %s", sqlite_path, sqlite3_errmsg(g_ctx.db));
669	        goto fail;
670	    }
671	    sqlite3_config(SQLITE_CONFIG_LOG, sqlite_log, NULL);
672	
673	    g_ctx.ready = true;
674	    return true;
675	
676	fail:
677	    free_schema(&g_ctx.schema);
678	    if (g_ctx.db) {
679	        sqlite3_close(g_ctx.db);
680	        g_ctx.db = NULL;
681	    }
682	    return false;
683	}
684	
685	/*
686	 * Feed a raw line into the pipeline.
687	 */
688	void processing_feed_line(const char *line)
689	{
690	    if (!g_ctx.ready) {
691	        LOG_ERR("processing not initialized");
692	        return;
693	    }
694	
695	    event_t evt = { .type = EVT_RECORD_INGESTED, .raw_line = line, .record = NULL, .message = NULL };
696	    dispatch_event(&evt);
697	
698	    char *error = NULL;
699	    record_t rec = {0};
700	
701	    /* Parse */
702	    if (!parse_line(line, &rec, &error)) {
703	        evt.type = EVT_PIPELINE_ERROR;
704	        evt.message = error;
705	        dispatch_event(&evt);
706	        LOG_ERR("%s", error);
707	        free(error);
708	        return;
709	    }
710	
711	    /* Validate */
712	    if (!validate_record(&rec, &g_ctx.schema, &error)) {
713	        evt.type = EVT_PIPELINE_ERROR;
714	        evt.record = &rec;
715	        evt.message = error;
716	        dispatch_event(&evt);
717	        LOG_ERR("%s", error);
718	        free(error);
719	        free_record(&rec);
720	        return;
721	    }
722	
723	    evt.type   = EVT_RECORD_VALIDATED;
724	    evt.record = &rec;
725	    dispatch_event(&evt);
726	
727	    /* Transform */
728	    transform_record(&rec);
729	    evt.type = EVT_RECORD_TRANSFORMED;
730	    dispatch_event(&evt);
731	
732	    /* Store */
733	    if (!store_record(g_ctx.db, &rec, &error)) {
734	        evt.type = EVT_PIPELINE_ERROR;
735	        evt.message = error;
736	        dispatch_event(&evt);
737	        LOG_ERR("%s", error);
738	        free(error);
739	        free_record(&rec);
740	        return;
741	    }
742	
743	    evt.type = EVT_RECORD_STORED;
744	    dispatch_event(&evt);
745	
746	    free_record(&rec);
747	}
748	
749	/*
750	 * Shutdown processing pipeline and free resources.
751	 */
752	void processing_shutdown(void)
753	{
754	    if (!g_ctx.ready) return;
755	
756	    event_t evt = { .type = EVT_SHUTDOWN, .raw_line = NULL, .record = NULL, .message = "shutdown" };
757	    dispatch_event(&evt);
758	
759	    /* Clean observers */
760	    pthread_mutex_lock(&g_ctx.obs_mtx);
761	    free(g_ctx.observers);
762	    g_ctx.observers = NULL;
763	    g_ctx.obs_cap = g_ctx.obs_len = 0;
764	    pthread_mutex_unlock(&g_ctx.obs_mtx);
765	    pthread_mutex_destroy(&g_ctx.obs_mtx);
766	
767	    free_schema(&g_ctx.schema);
768	
769	    if (g_ctx.db) {
770	        sqlite3_close(g_ctx.db);
771	        g_ctx.db = NULL;
772	    }
773	    g_ctx.ready = false;
774	}
