120	/* ---------- Schema --------------------------------------------------------- */
121	struct ssul_schema_s {
122	    size_t    nfields;
123	    char    **names;   /* field names */
124	    char     *types;   /* per-field type: ‘i’, ’f’, ‘s’ */
125	};
126	
127	static char type_from_token(const char *tok)
128	{
129	    if (strcasecmp(tok, "int")   == 0) return 'i';
130	    if (strcasecmp(tok, "float") == 0) return 'f';
131	    return 's';
132	}
133	
134	int __attribute__((weak))
135	ssul_schema_from_string(ssul_schema_t **out, const char *schema_str)
136	{
137	    if (!out || !schema_str) return -EINVAL;
138	
139	    ssul_schema_t *sch = calloc(1, sizeof(*sch));
140	    if (!sch) return -ENOMEM;
141	
142	    char *tmp = xstrdup(schema_str);
143	    char *save = NULL;
144	    char *field = strtok_r(tmp, ",", &save);
145	    while (field) {
146	        char *sep = strchr(field, ':');
147	        if (!sep) { free(tmp); ssul_schema_free(sch); return -EINVAL; }
148	        *sep = '\0';
149	        char *name  = field;
150	        char *typestr = sep + 1;
151	
152	        sch->names  = realloc(sch->names,  sizeof(char *) * (sch->nfields + 1));
153	        sch->types  = realloc(sch->types,  sizeof(char)   * (sch->nfields + 1));
154	        sch->names[sch->nfields] = xstrdup(name);
155	        sch->types[sch->nfields] = type_from_token(typestr);
156	        sch->nfields++;
157	
158	        field = strtok_r(NULL, ",", &save);
159	    }
160	    free(tmp);
161	    *out = sch;
162	    return 0;
163	}
164	
165	void __attribute__((weak))
166	ssul_schema_free(ssul_schema_t *schema)
167	{
168	    if (!schema) return;
169	    for (size_t i = 0; i < schema->nfields; ++i) free(schema->names[i]);
170	    free(schema->names);
171	    free(schema->types);
172	    free(schema);
173	}
