175	/* ---------- Transform ------------------------------------------------------ */
176	struct ssul_transform_s {
177	    size_t  n_proj;
178	    size_t *proj_idx;    /* indices to keep */
179	};
180	
181	int __attribute__((weak))
182	ssul_transform_parse(ssul_transform_t **out, const char *expr)
183	{
184	    if (!out || !expr) return -EINVAL;
185	
186	    const char prefix[] = "project:";
187	    if (strncmp(expr, prefix, sizeof(prefix) - 1) != 0) return -ENOTSUP;
188	
189	    ssul_transform_t *t = calloc(1, sizeof(*t));
190	    if (!t) return -ENOMEM;
191	
192	    char *tmp = xstrdup(expr + sizeof(prefix) - 1);
193	    char *save = NULL;
194	    char *tok = strtok_r(tmp, ",", &save);
195	    while (tok) {
196	        t->proj_idx = realloc(t->proj_idx, sizeof(size_t) * (t->n_proj + 1));
197	        t->proj_idx[t->n_proj++] = (size_t)(-1);   /* filled later by processor */
198	        tok = strtok_r(NULL, ",", &save);
199	    }
200	    free(tmp);
201	    *out = t;
202	    return 0;
203	}
204	
205	void __attribute__((weak))
206	ssul_transform_free(ssul_transform_t *t)
207	{
208	    if (!t) return;
209	    free(t->proj_idx);
210	    free(t);
211	}
