213	/* ---------- Processor ------------------------------------------------------ */
214	struct ssul_processor_s {
215	    const ssul_schema_t *schema;
216	    ssul_transform_t   **transforms;
217	    size_t               n_transforms;
218	    ssul_eventbus_t     *bus;
219	};
220	
221	static int csv_split(const char *line, char ***out_tokens, size_t *out_cnt)
222	{
223	    char **vec = NULL;
224	    size_t n   = 0;
225	    char *tmp  = xstrdup(line);
226	    char *save = NULL;
227	    char *tok  = strtok_r(tmp, ",\n\r", &save);
228	    while (tok) {
229	        vec = realloc(vec, sizeof(char*) * (n + 1));
230	        vec[n++] = xstrdup(tok);
231	        tok = strtok_r(NULL, ",\n\r", &save);
232	    }
233	    free(tmp);
234	    *out_tokens = vec;
235	    *out_cnt    = n;
236	    return 0;
237	}
238	
239	static void csv_free(char **tokens, size_t n)
240	{
241	    while (n--) free(tokens[n]);
242	    free(tokens);
243	}
244	
245	int __attribute__((weak))
246	ssul_processor_create(ssul_processor_t **out,
247	                      const ssul_schema_t *schema,
248	                      ssul_transform_t   *const *transforms,
249	                      size_t n_transforms,
250	                      ssul_eventbus_t *bus)
251	{
252	    if (!out || !schema || !bus) return -EINVAL;
253	    ssul_processor_t *p = calloc(1, sizeof(*p));
254	    if (!p) return -ENOMEM;
255	
256	    p->schema       = schema;
257	    p->n_transforms = n_transforms;
258	    if (n_transforms) {
259	        p->transforms = calloc(n_transforms, sizeof(ssul_transform_t*));
260	        for (size_t i = 0; i < n_transforms; ++i)
261	            p->transforms[i] = transforms[i];
262	    }
263	    p->bus          = bus;
264	    *out = p;
265	    return 0;
266	}
267	
268	void __attribute__((weak))
269	ssul_processor_free(ssul_processor_t *p)
270	{
271	    if (!p) return;
272	    free(p->transforms);
273	    free(p);
274	}
275	
276	/* returns 0 on success, ‑EINVAL on validation failures */
277	int __attribute__((weak))
278	ssul_processor_ingest_line(ssul_processor_t *p,
279	                           const char       *line,
280	                           ssul_stats_t     *stats,
281	                           char            **err_out)
282	{
283	    if (!p || !line || !stats) return -EINVAL;
284	
285	    char **tokens   = NULL;
286	    size_t ntokens  = 0;
287	    csv_split(line, &tokens, &ntokens);
288	
289	    bool ok = true;
290	    if (ntokens != p->schema->nfields) ok = false;
291	    else {
292	        for (size_t i = 0; i < ntokens; ++i) {
293	            char type = p->schema->types[i];
294	            char *end = NULL;
295	            switch (type) {
296	            case 'i':
297	                strtol(tokens[i], &end, 10);
298	                if (*end) ok = false;
299	                break;
300	            case 'f':
301	                strtod(tokens[i], &end);
302	                if (*end) ok = false;
303	                break;
304	            case 's':
305	                /* always valid */
306	                break;
307	            default:
308	                ok = false;
309	            }
310	            if (!ok) break;
311	        }
312	    }
313	
314	    if (ok) {
315	        p->bus->ok++;
316	        stats->ok_cnt++;
317	    } else {
318	        p->bus->err++;
319	        stats->fail_cnt++;
320	        if (err_out) *err_out = xstrdup("validation failed");
321	    }
322	
323	    csv_free(tokens, ntokens);
324	    return ok ? 0 : -EINVAL;
325	}
